#pragma once
#include <Arduino.h>
#include <type_traits>
// Interface languages of the screens. English and Russian are written in the code as
// t("English","Русский"); a language added after them comes from include/I18nTable.h, generated by
// tools/i18n.py from i18n/firmware/<lang>.json. The language number is stored in NVS
// ("lang"), so the order below never changes; new languages go to the end. A stored number this
// image does not have (the 13 upstream languages 2-14 that were removed) falls back to English.
enum Lang:uint8_t {LangEn,LangRu,LangCount};
extern const char* const langCodes[LangCount]; // "en", "ru", ...
extern const char* const langNames[LangCount]; // each in its own language
int langFromCode(const String& code); // -1 when unknown
bool langAvailable(uint8_t l);
uint8_t langStep(uint8_t l,int dir); // the next (dir>0) or previous available language
// The text in the interface language; a string without a translation shows English. tr("English","Русский")
// is a macro: the key of the translation (FNV-1a over English, 0x1f and Russian, as tools/i18n.py) is computed
// by the compiler. Pairs read from tables go through trPair().
constexpr uint32_t i18nFnv(const char* s,uint32_t h){while(*s)h=(h^uint8_t(*s++))*0x01000193u;return h;}
constexpr uint32_t i18nKey(const char* en,const char* ru){return i18nFnv(ru,(i18nFnv(en,0x811c9dc5u)^0x1fu)*0x01000193u);}
const char* trKey(const char* en,const char* ru,uint32_t key);
inline const char* trPair(const char* en,const char* ru){return trKey(en,ru,i18nKey(en,ru));}
#define tr(en,ru) trKey(en,ru,std::integral_constant<uint32_t,i18nKey(en,ru)>::value)
// "5 games": the number and the noun form its language needs. English and Russian are the arguments
// (number, space, form); translations place the number with {n} or leave it out.
String plural(unsigned n,const char* one,const char* many,const char* ru1,const char* ru2,const char* ru5);
// The language the site installer chose ("" when the image was not installed from the site).
String installLanguage();

// Drawing text.
// Fonts tried after `font` for a glyph it lacks: Latin-1, then the Latin Extended subset
// (include/I18nFonts.h). Null-terminated.
const uint8_t* const* fallbackFonts(const uint8_t* font);
bool fontHasGlyph(const uint8_t* font,uint16_t cp);
// Two cells for CJK and other wide glyphs, one otherwise: column counting on the 128x64 screens.
uint8_t glyphCells(uint32_t cp);
uint32_t utf8Next(const String& s,unsigned& i); // the codepoint at i; i moves past it
